import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1185, own='cte_108.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 769 Forensic Science ----
H("769.d.1.A",3,"A student notices that a stain on a mock evidence card turned brown after a day and asks why. This is an example of:","asking a question based on an observation",["writing a conclusion","building a model","buying supplies"],"Science begins with questions from observations.")
H("769.d.1.A",4,"Which is a testable question for a forensic lab class?","Does the type of surface change how fast a fingerprint powder sticks?",["Is forensic science cool?","Who is the best detective?","Should crime be illegal?"],"Testable questions can be answered with data.")
H("769.d.1.B",3,"A class designs a controlled test that dusts the same print on glass, plastic and wood and compares how clear each lift is. This applies scientific practices to plan a:","comparative investigation",["fashion show","bake sale","field trip"],"Comparing groups under similar conditions.")
H("769.d.1.B",4,"In a comparative lab test, the factor the students deliberately change is called the:","independent variable",["dependent variable","constant","control group only"],"Independent variable is manipulated.")
H("769.d.1.C",3,"Before pouring a chemical to develop prints, a student puts on goggles, gloves and an apron and checks the ventilation. This uses appropriate:","safety equipment and practices",["decor choices","music settings","lunch breaks"],"Wear PPE for chemicals.")
H("769.d.1.C",4,"If a chemical splashes into a student's eyes in the lab, the first step is to:","flush the eyes at the eyewash station and alert the teacher",["wipe with a paper towel","keep working","wait to see if it hurts"],"Eyewash right away.")
H("769.d.1.D",3,"A student uses a digital scale, a calculator and a stereo microscope to measure and record fiber samples. This uses appropriate:","tools and equipment to collect and analyze data",["props for a play","party supplies","office furniture"],"Select the right tools.")
H("769.d.1.D",4,"A stereo microscope is most useful in forensics for:","viewing small trace evidence such as fibers in detail",["measuring temperature","weighing liquids","timing reactions"],"Magnifies trace evidence.")
H("769.d.1.E",3,"A student records a footprint length as 27.5 cm using a metric ruler, not in inches. This collects quantitative data using the:","International System of Units (SI)",["Roman numeral system","customary cooking units","random units"],"SI units are standard in science.")
H("769.d.1.E",4,"Which measurement is in an SI base unit?","a mass of 0.25 kilograms",["a mass of 9 ounces","a length of 4 inches","a volume of 2 cups"],"Kilogram is SI.")
H("769.d.1.F",3,"A group puts bullet-casing diameters into a table and also keeps notes on the color and condition of each casing. This organizes quantitative and qualitative data using:","tables, graphs and descriptive notes",["unlabeled scraps","memory alone","loose pages"],"Both kinds of data are organized.")
H("769.d.1.F",4,"A description such as 'rusty and scratched' is an example of:","qualitative data",["quantitative data","a variable only","a control"],"Qualitative = descriptive.")
H("769.d.1.G",3,"A student builds a scale model of a room and places chalk marks to represent where a blood pattern was found. This develops and uses a:","model to represent a system or phenomenon",["perfect copy of reality","recipe","guess"],"Models represent systems.")
H("769.d.1.G",4,"A model of a crime scene is useful because it:","helps visualize and test ideas about what happened",["replaces all evidence","proves guilt alone","eliminates doubt"],"Models support analysis.")
H("769.d.1.H",3,"A student says her hypothesis is proved a theory after one successful test. A teacher explains that a hypothesis is a tentative explanation, while theories and laws are far better supported. This distinguishes:","hypotheses, theories and laws",["verbs, nouns and adjectives","angles, lines and arcs","fractions, decimals and ratios"],"Know the levels of scientific explanation.")
H("769.d.1.H",4,"A student says gravity is only a theory, so it is just a guess. What is wrong with this statement?","A scientific theory is a well-tested explanation backed by a large body of evidence",["A theory is the same thing as a hypothesis","A theory has no supporting evidence","A theory is a guess that scientists have not yet tested"],"Theories are well tested.")
H("769.d.2.A",3,"A crime-scene model drawn at 1:50 scale shows relative positions but not the textures and smells of the room. This identifies advantages and limitations of models such as their:","size, scale and simplification",["color and taste","name and number","font and style"],"Models simplify reality.")
H("769.d.2.A",4,"One limitation of a small-scale model of a room is that it may:","leave out details of the actual environment",["be perfectly accurate","contain more detail than reality","never be useful"],"Models omit details.")
H("769.d.2.B",3,"After recording the height of 30 bloodstain drops, a student calculates the mean and notices a pattern at higher drop heights. This analyzes data by identifying:","significant statistical features and patterns",["handwriting styles","music genres","recipe steps"],"Look for patterns in data.")
H("769.d.2.B",4,"The mean of the values 4, 6 and 8 is:","6",["4","8","18"],"(4+6+8)/3 = 6.")
H("769.d.2.C",3,"A student uses the speed of a bullet and the time to hit a target to find the distance traveled. This uses mathematical calculations to assess:","quantitative relationships in data",["spelling rules","map colors","menu prices"],"Calculations reveal relationships.")
H("769.d.2.C",4,"A bullet travels at 300 meters per second for 2 seconds. How far does it travel?","600 meters",["150 meters","302 meters","1.5 meters"],"Distance = speed × time.")
H("769.d.2.D",3,"After testing two dusting methods, a team checks whether the setup was fair and whether the design could be improved. This evaluates:","experimental and engineering designs",["art contests","spelling quizzes","cooking contests"],"Evaluate design quality.")
H("769.d.2.D",4,"A fair experimental design changes:","only one variable at a time",["every variable","no variables","the results afterward"],"Control variables.")
H("769.d.3.A",3,"After lifting prints from three surfaces, a team writes that glass held the clearest prints and backs it up with their data table and a photo. This develops explanations supported by:","data and models",["opinion alone","rumors","guesses"],"Explanations rely on evidence.")
H("769.d.3.A",4,"A strong scientific explanation should be:","supported by evidence from the investigation",["based on a feeling","based on popularity","independent of data"],"Evidence supports claims.")
H("769.d.3.B",3,"Students present their findings as a lab report alone and then discuss them in a group to refine the conclusions. This communicates explanations:","individually and collaboratively",["only silently","only in secret","only at random"],"Share and refine.")
H("769.d.3.B",4,"A good lab report should include:","a clear claim, evidence and reasoning",["only opinions","only photos","only titles"],"Claim-evidence-reasoning.")
H("769.d.3.C",3,"In a debate about whether a stain is blood, a student listens, cites test results and disagrees politely. This engages respectfully in:","scientific argumentation",["name-calling","quarreling","shouting"],"Respectful argument with evidence.")
H("769.d.3.C",4,"When a classmate challenges your conclusion, the best response is to:","explain your evidence and consider their point",["ignore them","insult them","change the data"],"Respond with evidence.")
H("769.d.4.A",3,"A student reads a forensic report and checks whether its claims follow from the evidence and whether the methods were sound. This analyzes, evaluates and critiques:","scientific explanations and solutions",["movie scripts","sports rules","menus"],"Critique explanations.")
H("769.d.4.A",4,"Critiquing a scientific claim includes asking:","does the evidence really support it?",["who is the author's neighbor?","what color is the cover?","how long is the title?"],"Evidence check.")
H("769.d.4.B",3,"A student explains how the discovery of DNA fingerprinting changed how investigators identify suspects and what scientists thought about heredity. This relates the impact of research on:","scientific thought and society",["lunch menus","uniform colors","weather maps"],"Research changes thinking and society.")
H("769.d.4.B",4,"The development of DNA profiling in the 1980s most changed forensic science by allowing:","identification of individuals from biological samples",["faster typing","brighter lights","cheaper clothing"],"DNA identification.")
H("769.d.4.C",3,"A student visits a science museum, interviews a lab analyst and reads a journal article to learn about careers. This researches and explores:","resources such as museums, libraries and professional organizations",["only video games","only gossip","only advertising"],"Use varied resources.")
H("769.d.4.C",4,"A professional organization is a good resource for learning about forensic careers because it provides:","information on training, standards and certification",["party invitations","sports scores","game cheats"],"Professional bodies set standards.")
H("769.d.5.A",3,"A timeline starts with the first use of fingerprints for identification and ends with rapid DNA machines. This analyzes the historical development and current advancements of:","different forensic science fields",["pottery methods","singing styles","gardening tools"],"Forensics evolved over time.")
H("769.d.5.A",4,"A recent advancement in forensic science is:","rapid DNA analysis",["the quill pen","carbon paper","telegraph keys"],"Modern advance.")
H("769.d.5.B",3,"A student explains that Alphonse Bertillon's body measurements, Edmond Locard's exchange principle and Alec Jeffreys's DNA fingerprinting each shaped forensics. This explains significant contributions to the:","development of forensic science",["development of cooking","development of dance","development of gaming"],"Many scientists contributed.")
H("769.d.5.B",4,"Locard's exchange principle states that:","every contact leaves a trace",["no contact leaves anything","only blood is evidence","only prints matter"],"Contact transfers evidence.")
H("769.d.6.A",3,"A forensic analyst refuses to change a result to help a prosecutor win and reports data honestly even when it hurts the case. This summarizes the ethical standards of:","a forensic science professional",["a salesperson","a racer","a chef"],"Objectivity and honesty.")
H("769.d.6.A",4,"An ethical forensic scientist should report results that are:","objective and based on the evidence",["favorable to one side","adjusted to fit a theory","kept secret"],"Objectivity matters.")
H("769.d.6.B",3,"A student learns the terms and steps for packaging, sealing, labeling and tracking each item from a scene to the lab. This identifies terminology and procedures for:","maintaining chain of custody and evidence integrity",["publishing a novel","planning a trip","running a race"],"Procedures protect evidence integrity.")
H("769.d.6.B",4,"Evidence is usually sealed and labeled with the date, time and collector's initials in order to:","document who handled it and prevent tampering",["make it heavier","make it pretty","make it cheaper"],"Chain of custody.")
H("769.d.6.C",3,"A class reviews the difference between a laboratory's accreditation, standard operating procedures and quality assurance checks. This identifies terminology and procedures for:","laboratory quality assurance and control",["lunch menus","bus routes","parking permits"],"Labs use QA/QC.")
H("769.d.6.C",4,"A control sample run alongside evidence helps a lab to:","confirm that the test is working correctly",["hide errors","speed the test","skip documentation"],"Controls validate tests.")
H("769.d.6.D",3,"An analyst who expects a suspect to be guilty tends to see matches that are not really there. This researches and discusses the effect of biases such as:","confirmation bias on forensic results",["weather on prints","color on cloth","music on speech"],"Bias can distort analysis.")
H("769.d.6.D",4,"One way to reduce confirmation bias in a forensic lab is to:","have a second examiner review the results blind to the case details",["let the detective choose","tell the analyst the suspect","skip peer review"],"Blind verification.")
H("769.d.6.E",3,"A judge decides whether an expert's methods are scientifically reliable and relevant before the jury hears the testimony. This compares the admissibility of expert testimony under:","the Frye and Daubert standards",["school dress codes","parking rules","recess rules"],"Frye and Daubert govern admissibility.")
H("769.d.6.E",4,"Under the Daubert standard, a judge considers whether a method:","has been tested, peer reviewed and has a known error rate",["is popular","is old","is expensive"],"Daubert factors.")
H("769.d.7.A",3,"A student researches the degrees, certifications and lab experience required to become a DNA analyst or a toxicologist. This explores:","discipline-specific requirements for careers in forensic science",["hobby clubs","hair salons","sports leagues"],"Careers have specific requirements.")
H("769.d.7.A",4,"Most forensic analyst jobs require at least a:","bachelor's degree in a natural science",["driver's permit only","fashion portfolio","music audition"],"Science degree is typical.")
H("769.d.7.B",3,"Students compare what a crime scene investigator, a lab analyst, a medical examiner and a forensic attorney do. This differentiates:","the roles and responsibilities of professionals in the criminal justice system",["recipes of cooks","jobs of pilots","tasks of farmers"],"Roles differ.")
H("769.d.7.B",4,"The professional who investigates deaths and determines cause and manner of death is the:","medical examiner or coroner",["court clerk","bailiff","juror"],"Death investigations.")
H("769.d.7.C",3,"A chart shows toxicology testing fluids for drugs, trace analysis examining fibers and digital forensics recovering files. This differentiates the functions of:","various forensic science disciplines",["art classes","sports teams","music bands"],"Disciplines specialize.")
H("769.d.7.C",4,"A discipline that analyzes bodily fluids for drugs and poisons is:","toxicology",["ballistics","document examination","entomology"],"Toxicology analyzes substances in fluids.")
H("769.d.8.A",3,"At a crime scene, one person photographs, one sketches, one collects evidence and one keeps the log. This explains the roles and tasks needed to complete:","a crime scene examination",["a movie shoot","a school play","a cooking class"],"Teams divide scene tasks.")
H("769.d.8.A",4,"The person who logs everyone entering and leaving the scene is the:","scene recorder or entry log officer",["jury foreman","witness","defendant"],"Scene access log.")
H("769.d.8.B",3,"An examiner writes her observations in order, with exact measurements and no guesses, so another investigator could use them months later. This develops a detailed, technical:","written record based on observations and facts",["fiction story","poem","opinion column"],"Technical notes record facts.")
H("769.d.8.B",4,"In crime-scene notes, it is best to record:","facts that were observed and measured",["assumptions","gossip","jokes"],"Objective notes.")
H("769.d.8.C",3,"A student explains why officers generally need a warrant or consent, and how the plain-view exception works before searching a home. This discusses elements of criminal law that guide:","search and seizure of evidence",["school registration","traffic reports","menu design"],"Fourth Amendment limits searches.")
H("769.d.8.C",4,"A warrant must be supported by:","probable cause",["a hunch","an anonymous rumor","a guess"],"Probable cause is required.")
H("769.d.8.D",3,"A team first walks a simulated scene along a grid, then makes a second pass in the opposite direction to catch what was missed. This conducts:","a primary and secondary systematic search",["a random wander","a single glance","a quick skim"],"Second pass catches misses.")
H("769.d.8.D",4,"A common systematic search pattern for a large outdoor scene is the:","grid or lane search",["random search","speed search","guess search"],"Grid search pattern.")
H("769.d.8.E",3,"A technician takes overall, midrange and close-up photographs with a scale in the frame before moving anything. This documents a scene using:","photographic or audiovisual equipment",["handwritten letters","sound effects","poster boards"],"Photography records the scene.")
H("769.d.8.E",4,"A scale placed next to an object in a scene photograph allows:","accurate measurement from the picture",["color matching","time tracking","noise reduction"],"Scales give size.")
H("769.d.8.F",3,"A student draws a room layout using a measuring tape and coordinates from two fixed points to mark where each item lay. This generates a:","crime scene sketch including coordinates",["cartoon","family tree","menu board"],"Sketches use measurements.")
H("769.d.8.F",4,"In a triangulation sketch, an item's position is recorded by measuring its distance from:","two fixed reference points",["one moving object","no reference","a witness's guess"],"Triangulation uses fixed points.")
H("769.d.8.G",3,"An investigator places a bloody shirt in a paper bag, seals it, labels it and keeps it dry to prevent mold. This demonstrates proper techniques for:","collecting, packaging and preserving evidence",["tossing evidence","exposing evidence","mixing evidence"],"Paper bags protect biological items.")
H("769.d.8.G",4,"Wet biological evidence should be packaged in a:","paper container so it can breathe",["plastic bag sealed tight","metal can","glass jar"],"Plastic traps moisture.")
H("769.d.9.A",3,"A student sorts a set of prints into those with concentric circles, those with a ridge that enters and exits on the same side, and those with a gentle wave shape. This compares the three major fingerprint patterns:","arches, loops and whorls",["squares, rectangles and circles","spirals, dots and dashes","stars, hearts and moons"],"Three basic patterns.")
H("769.d.9.A",4,"An examiner reviewing a stack of ten-print cards finds that most fingers show a ridge that enters and exits on the same side. Which pattern is this?","loop",["whorl","arch","tented arch only"],"Loops are the most frequent pattern.")
H("769.d.9.B",3,"An examiner marks places where a ridge splits in two, where it ends abruptly and where a tiny ridge sits alone. This identifies the minutiae including:","bifurcations, ridge endings and islands",["freckles, moles and veins","thumbs, palms and wrists","arches, whorls and loops only"],"Minutiae are ridge details.")
H("769.d.9.B",4,"A ridge that splits into two branches is called a:","bifurcation",["ridge ending","island","delta"],"Bifurcation = fork.")
H("769.d.9.C",3,"A print left in wet paint can be seen and felt, one in dust is visible, and one on glass from skin oils needs development. This distinguishes:","patent, plastic and latent impressions",["sticky, shiny and dull coats","red, blue and green marks","open, closed and locked prints"],"Print types differ in visibility.")
H("769.d.9.C",4,"A fingerprint left in soft wax or putty is a:","plastic print",["latent print","patent print","chemical print"],"Plastic prints are 3D impressions.")
H("769.d.9.D",3,"A student brushes powder on a smooth glass slide and lifts the print with clear tape onto a card. This performs development and lifting of latent prints on:","nonporous surfaces",["porous paper only","skin only","water"],"Powder works on smooth surfaces.")
H("769.d.9.D",4,"Fingerprint powder works best on:","smooth, nonporous surfaces such as glass",["rough fabric","wet sand","unfinished wood"],"Nonporous surfaces hold residue on top.")
H("769.d.9.E",3,"On a sheet of paper, a technician uses a solution that reacts with amino acids in sweat and turns the print purple. This develops latent prints using:","chemical processes such as ninhydrin",["fingerprint powder","oil paint","chalk"],"Ninhydrin reacts with amino acids.")
H("769.d.9.E",4,"Cyanoacrylate (super glue) fuming is used to develop prints on:","nonporous items such as plastic and metal",["porous paper only","water","fabric only"],"Fuming builds a white polymer.")
H("769.d.9.F",3,"A latent print from a scene is scanned and compared with millions of stored records to find possible matches. This explains the:","Integrated Automated Fingerprint Identification System (IAFIS)",["Internet music system","Insurance filing system","Island fishing system"],"IAFIS is the national fingerprint database.")
H("769.d.9.F",4,"After a database returns candidate matches for a print, a trained examiner must:","verify the match by direct comparison",["accept it without review","ignore the list","delete the print"],"Human verification is needed.")

H("769.d.10.A",3,"An examiner notes that a pry bar's width matches a groove in a door frame, but tiny nicks inside the groove vary from tool to tool. This analyzes the class and individual characteristics of:","tool mark impressions",["tire tracks only","hair strands","blood spatters"],"Class = shape; individual = wear nicks.")
H("769.d.10.A",4,"A screwdriver's blade width is an example of a:","class characteristic",["individual characteristic","random event","contaminant"],"Class characteristics are shared by a group.")
H("769.d.10.B",3,"A shoe print at a scene shows the same sole pattern as a suspect's shoe, plus a unique cut across the heel. This analyzes class and individual characteristics of:","footwear impressions",["tire impressions","tool marks","fingerprints"],"Wear and damage make shoes unique.")
H("769.d.10.B",4,"A cut or nick that appears only on one shoe sole is an:","individual characteristic",["class characteristic","manufacturing design","brand name"],"Acquired damage is individual.")
H("769.d.10.C",3,"A cast of a tire track shows the tread design and brand but also a unique gouge from a nail. This analyzes class and individual characteristics of:","tire tread impressions",["footwear impressions","glass fractures","hair"],"Tread design is class; gouge is individual.")
H("769.d.10.C",4,"The tread pattern of a tire that is common to many tires of one model is a:","class characteristic",["individual characteristic","DNA marker","fingerprint ridge"],"Pattern is a class trait.")
H("769.d.10.D",3,"A student pours casting material into a track at a mock scene and later compares it with test impressions of a suspect's shoes. This compares:","impression evidence with known exemplars",["recipes with menus","maps with legends","graphs with labels"],"Exemplars are known samples for comparison.")
H("769.d.10.D",4,"A known sample used for comparison with evidence is called an:","exemplar",["artifact","contaminant","outlier"],"Exemplars come from known sources.")
H("769.d.11.A",3,"At a mock scene, a technician uses tweezers and tape lifts to gather strands from a victim's clothing and places each in a separate fold. This demonstrates how to collect:","hair and fiber evidence",["glass shards","blood spatter","gunshot residue"],"Trace evidence is collected carefully.")
H("769.d.11.A",4,"Each hair or fiber item should be packaged:","separately to prevent cross-contamination",["together in one bag","loosely in a pocket","taped on a wall"],"Separate packaging.")
H("769.d.11.B",3,"A lab technician views a strand on a comparison microscope next to a known sample and notes color, scale pattern and thickness. This performs:","analysis of hair and fiber evidence using forensic science procedures",["a taste test","a typing test","a driving test"],"Microscopy compares traits.")
H("769.d.11.B",4,"A comparison microscope allows an examiner to:","view two samples side by side",["freeze samples","dissolve samples","print samples"],"Side-by-side comparison.")
H("769.d.11.C",3,"Under magnification, a human hair shows a thin medulla while a cat hair shows a wide, ladder-like one. This compares the microscopic characteristics of:","human hair and non-human hair",["glass and plastic","paper and cloth","blood and saliva"],"Medulla patterns differ by species.")
H("769.d.11.C",4,"The center core of a hair shaft is the:","medulla",["cuticle","cortex","root bulb"],"Medulla is the central canal.")
H("769.d.11.D",3,"A student labels a diagram of a single strand showing the outer scales, the middle layer with pigment and the central canal. This describes and illustrates the microscopic characteristics of:","hair",["glass","paint","soil"],"Cuticle, cortex and medulla.")
H("769.d.11.D",4,"The outer layer of a hair, made of overlapping scales, is the:","cuticle",["medulla","cortex","follicle"],"Cuticle = outer scale layer.")
H("769.d.11.E",3,"A technician burns a small thread: one smells like burning hair and turns to ash, and another melts into a hard bead. This differentiates between:","natural and synthetic fibers",["glass and plastic","metal and wood","paint and ink"],"Burn tests help classify fibers.")
H("769.d.11.E",4,"Cotton and wool are examples of:","natural fibers",["synthetic fibers","glass fibers","metal fibers"],"Plant and animal fibers.")
H("769.d.12.A",3,"At a mock scene with a broken window, a technician collects shards from the inside and outside surfaces into separate containers. This demonstrates how to collect and preserve:","glass evidence",["paint chips","blood stains","soil layers"],"Glass is collected carefully.")
H("769.d.12.A",4,"Glass fragments should be packaged in:","rigid, sealed containers to protect them",["open plastic bags","paper towels","envelopes only"],"Prevent breakage and loss.")
H("769.d.12.B",3,"Students compare window glass, tempered car glass and heat-resistant lab glass by melting behavior and breaking pattern. This compares the composition of:","various types of glass such as soda lime and borosilicate",["wood and plastic","paper and cloth","metal and rubber"],"Glass types differ in composition.")
H("769.d.12.B",4,"Borosilicate glass is known for its:","resistance to heat",["softness","ability to bounce","color change"],"Used in lab glassware.")
H("769.d.12.C",3,"On a broken window, a technician examines the rib marks on the edge of the radial cracks and the sides of the concentric cracks to learn where the object struck from. This determines:","the direction of a projectile by examining glass fractures",["the age of the glass","the color of the glass","the shape of the frame"],"Fracture patterns indicate direction.")
H("769.d.12.C",4,"In a bullet hole in glass, the crater (cone) widens on the side:","where the projectile exits",["where the projectile enters","at the top","at the bottom"],"Exit side is cratered.")
H("769.d.12.D",3,"A lab places a glass fragment in oil and heats it until it seems to vanish, then records the temperature to compare with another fragment. This defines and uses the:","refractive index of glass",["boiling point of oil","density of wood","weight of paper"],"Refractive index is a bending-of-light measure.")
H("769.d.12.D",4,"Refractive index describes how much a material:","bends light",["conducts heat","absorbs water","reflects sound"],"Light bending.")
H("769.d.13.A",3,"A forensic examiner studies ink, paper and printing to decide whether a contract was altered after signing. This researches the different types of examinations performed on:","questioned documents",["blood patterns","tire tracks","bite marks"],"Document examination.")
H("769.d.13.A",4,"One thing a document examiner may test is whether:","two inks are chemically different",["a signer is happy","a paper is soft","a pen is expensive"],"Ink differentiation.")
H("769.d.13.B",3,"A teller shines ultraviolet light on a bill to see a hidden strip, and checks for a watermark and color-shifting ink. This investigates security features of:","U.S. and foreign currency",["library cards","bus passes","movie tickets"],"Currency has security features.")
H("769.d.13.B",4,"A faint image seen when a bill is held up to light is a:","watermark",["serial stamp","mint seal","bank stamp"],"Watermark security feature.")
H("769.d.13.C",3,"An examiner compares an unknown note with known writing samples by looking at slant, spacing and letter forms. This performs:","handwriting comparisons with exemplars",["fingerprint dusting","DNA profiling","soil testing"],"Handwriting characteristics are compared.")
H("769.d.13.C",4,"A good handwriting exemplar is one that:","is written naturally by the suspect under similar conditions",["is traced","is copied from the note","is scribbled quickly"],"Natural writing is best.")
H("769.d.14.A",3,"A student takes apart a model of a pistol and a rifle to show the barrel, hammer or firing pin, and trigger. This describes the mechanism of modern firearms such as:","long guns and handguns",["bows and arrows","swords and shields","clubs and spears"],"Firearms share basic parts.")
H("769.d.14.A",4,"In a firearm, the part that strikes the primer to ignite the cartridge is the:","firing pin",["trigger guard","sight","magazine spring"],"Firing pin initiates ignition.")
H("769.d.14.B",3,"An examiner looks at the striations on a bullet and the marks left on a cartridge case to learn about the gun that fired it. This identifies components and characteristics of:","bullet and cartridge casings",["glass and plastic","paper and cloth","wood and metal"],"Marks reveal the gun used.")
H("769.d.14.B",4,"Spiral grooves inside a gun barrel leave marks on a bullet called:","rifling marks or striations",["scorch marks","fingerprints","watermarks"],"Rifling marks.")
H("769.d.14.C",3,"A swab from a suspect's hand is tested for tiny particles of lead, barium and antimony. This describes the composition and method of analysis for:","gunshot residue",["glass dust","paint flakes","soil grains"],"GSR contains characteristic elements.")
H("769.d.14.C",4,"Gunshot residue particles are most often identified using a:","scanning electron microscope with elemental analysis",["kitchen scale","ruler","thermometer"],"SEM-EDS is standard.")
H("769.d.14.D",3,"Using strings and a protractor at a mock scene, students line up two bullet holes to estimate where a shot came from. This conducts and calculates:","trajectory analysis of bullet strikes",["recipe scaling","map scaling","time zones"],"String and angle show path.")
H("769.d.14.D",4,"Investigators use string to show the path of a bullet because a bullet's path is nearly a:","straight line over short distances",["circle","spiral","zigzag"],"Short-range paths are straight.")
H("769.d.14.E",3,"A detective wants to learn whether a gun used in one shooting is tied to casings found at other crime scenes in different cities. This identifies the type of information available through the:","National Integrated Ballistic Information Network (NIBIN)",["National Weather Service","National Park Service","National Library"],"NIBIN links ballistic evidence.")
H("769.d.14.E",4,"Two unconnected shootings in different counties turn up casings fired from the same weapon. Which resource would most likely reveal that link?","the national ballistic imaging network, NIBIN",["a fingerprint database only","a weather service","a postal tracking system"],"NIBIN correlates casing images across cases.")
H("769.d.15.A",3,"A student explains that one lab measures drug levels in blood to see impairment, while another identifies a powder as an illegal drug. This differentiates between:","toxicological analysis and controlled substance analysis",["spelling and grammar","addition and subtraction","history and geography"],"Different questions, different analyses.")
H("769.d.15.A",4,"Toxicology typically focuses on:","drugs and poisons in bodily samples",["tool marks","tire tracks","handwriting"],"Toxicology = body fluids/tissues.")
H("769.d.15.B",3,"A chart sorts drugs by medical use and risk of abuse into Schedule I through V. This classifies controlled substances under:","the Controlled Substances Act schedules",["the zoning code","the tax code","the fire code"],"Schedules rank by use and abuse potential.")
H("769.d.15.B",4,"Schedule I substances are defined as having:","high abuse potential and no accepted medical use",["low abuse potential","accepted medical use","no regulation"],"Schedule I definition.")
H("769.d.15.C",3,"A technician first runs a quick color test on an unknown powder and then confirms its identity using an instrument that separates and identifies compounds. This identifies unknowns using:","presumptive and confirmatory procedures",["guessing and checking","taste and smell","luck and chance"],"Quick screen then confirm.")
H("769.d.15.C",4,"A presumptive test is one that:","gives a quick, preliminary indication",["proves identity beyond doubt","replaces confirmation","is never used"],"Needs confirmation.")
H("769.d.16.A",3,"A toxicologist explains how a drug enters blood, spreads to organs, is broken down by the liver and leaves through urine. This explains:","absorption, distribution, metabolism and elimination",["sorting, filing and shipping","reading, writing and speaking","jumping, running and kicking"],"ADME describes drug processing.")
H("769.d.16.A",4,"The liver mainly handles which step of drug processing?","metabolism",["absorption","distribution","elimination only"],"Liver metabolizes drugs.")
H("769.d.16.B",3,"A lab screens a blood sample with an immunoassay and then confirms any positives using mass spectrometry. This describes presumptive and confirmatory procedures as they relate to:","toxicology",["fiber analysis","firearm analysis","document analysis"],"Screen then confirm.")
H("769.d.16.B",4,"Gas chromatography-mass spectrometry is commonly used as a:","confirmatory test",["presumptive test","field test","taste test"],"GC-MS confirms identity.")
H("769.d.16.C",3,"An analyst reads a chart showing a blood alcohol level of 0.10 and compares it with the legal limit of 0.08. This interprets:","results from presumptive and confirmatory procedures",["menus","maps","plays"],"Interpret numerical results.")
H("769.d.16.C",4,"A blood alcohol concentration above the legal limit of 0.08 means a driver is:","over the legal limit",["under the limit","sober by law","exempt"],"0.10 exceeds 0.08.")
H("769.d.16.D",3,"Before testing, a lab technician wears gloves, cleans the bench and uses a new pipette tip for each sample. This explains the precautions necessary for:","proper handling of toxicological samples and avoiding contamination",["decorating a room","playing games","storing food"],"Contamination control.")
H("769.d.16.D",4,"Using a clean tool for every sample prevents:","cross-contamination",["evaporation","freezing","labeling"],"Avoid mixing samples.")
H("769.d.17.A",3,"A blood drop that hits a smooth tile looks round, while one that hits rough wood spreads with irregular edges. This analyzes blood stain patterns based on:","surface type and appearance",["music type","paint color","room size"],"Surface affects pattern.")
H("769.d.17.A",4,"A long, narrow bloodstain with a pointed tail suggests a drop that:","hit the surface at a low angle",["fell straight down","was wiped","was dried"],"Elongated stain indicates an angle.")
H("769.d.17.B",3,"On a floor that has been cleaned, a technician sprays a reagent that glows to reveal traces of blood. This explains the methods of:","chemically enhancing latent blood patterns using luminol",["cleaning fingerprints","painting surfaces","testing fibers"],"Luminol reveals hidden blood.")
H("769.d.17.B",4,"Luminol is used at a scene to:","reveal latent blood stains",["identify gunshot residue","find fibers","measure glass"],"Luminol chemiluminescence.")
H("769.d.17.C",3,"A technician rubs a swab on a stain and adds a reagent that changes color if blood might be present. This conducts and interprets:","blood presumptive tests",["fingerprint tests","handwriting tests","tire tests"],"Presumptive tests indicate possible blood.")
H("769.d.17.C",4,"A positive presumptive test for blood means that:","blood may be present and further testing is needed",["blood is definitely human","the suspect is guilty","the stain is old"],"Presumptive needs confirmation.")
H("769.d.18.A",3,"A student labels samples of blood, saliva, hair with root and skin cells and uses clean gloves and swabs for each one. This identifies types of biological samples and practices proper:","collection techniques",["storage in sunlight","sharing tools","skipping labels"],"Proper collection avoids contamination.")
H("769.d.18.A",4,"Biological samples are usually dried before packaging to:","prevent mold and degradation",["increase weight","change color","add moisture"],"Dryness preserves DNA.")
H("769.d.18.B",3,"A student explains that type A blood has A antigens on red cells and anti-B antibodies in plasma. This identifies red blood cell:","antigens and antibodies relating to blood typing",["bones and joints","hairs and fibers","tools and tires"],"ABO system.")
H("769.d.18.B",4,"A person with type O blood has red cells that carry:","no A or B antigens",["a mix of A and B antigens","only the A antigen","only the B antigen"],"Type O has no A or B antigens.")
H("769.d.18.C",3,"A model of a twisted ladder with sugar-phosphate rails and base-pair rungs represents a:","DNA molecule",["protein chain","fat molecule","starch grain"],"Double helix.")
H("769.d.18.C",4,"In DNA, adenine pairs with:","thymine",["cytosine","guanine","uracil"],"A pairs with T.")
H("769.d.18.D",3,"A lab extracts DNA, copies targeted regions by PCR and separates the fragments to create a profile. This explains the analytical procedure of:","generating a DNA profile",["building a model plane","editing a video","baking bread"],"Extract, amplify, separate.")
H("769.d.18.D",4,"The step in which specific DNA regions are copied many times is:","polymerase chain reaction (PCR)",["centrifugation","staining","freezing"],"PCR amplifies DNA.")
H("769.d.18.E",3,"Besides nuclear DNA, a lab may test mitochondrial DNA from old hair shafts and Y-STR markers to track male lineage. This explains the different methodologies for:","types of DNA testing",["types of fibers","types of glass","types of tires"],"Different tests suit different samples.")
H("769.d.18.E",4,"Mitochondrial DNA is inherited from the:","mother",["father","both parents equally","neither"],"Maternal inheritance.")
H("769.d.18.F",3,"A graph of peaks shows allele positions at each location in a DNA sample, with two peaks at heterozygous sites. This interprets the components of an:","electropherogram",["thermometer","barometer","compass"],"Peaks are alleles.")
H("769.d.18.F",4,"In an electropherogram, a single tall peak at a location often means the person is:","homozygous at that location",["heterozygous","absent","contaminated"],"One allele type.")
H("769.d.18.G",3,"Investigators upload a profile to a national database that links offenders, arrestees and crime-scene samples. This explores DNA databasing systems such as:","the Combined DNA Index System (CODIS)",["the Combined Weather System","the Common Reading System","the Central Menu System"],"CODIS links DNA profiles.")
H("769.d.18.G",4,"A 'cold hit' in a DNA database occurs when:","a crime-scene profile matches a profile with no previous suspect",["no match is found","a profile is deleted","a sample is lost"],"Cold hit links to unknown suspects.")
H("769.d.19.A",3,"Rigor mortis stiffens a body, algor mortis cools it and livor mortis causes purple pooling of blood in low areas. This explains the principles used to estimate:","the time since death",["the cause of a fire","the age of a tire","the weight of a bullet"],"Postmortem changes aid time estimates.")
H("769.d.19.A",4,"The pooling of blood in the lowest parts of a body after death is called:","livor mortis",["rigor mortis","algor mortis","autolysis only"],"Livor = lividity.")
H("769.d.19.B",3,"A medical examiner notes jagged tears with bridging tissue and distinguishes them from clean cuts with smooth edges. This differentiates between types of:","wound patterns such as lacerations and incised wounds",["glass types","fiber types","paper types"],"Wound edges reveal mechanism.")
H("769.d.19.B",4,"A wound with ragged, irregular edges caused by blunt force is called a:","laceration",["incision","puncture only","burn"],"Lacerations are tears.")
H("769.d.19.C",3,"A student reads an autopsy report that lists injuries, organ findings and toxicology to decide how and why a person died. This determines the:","cause and manner of death",["age of a building","cost of a trial","speed of a car"],"Autopsy determines cause and manner.")
H("769.d.19.C",4,"The manner of death can be classified as natural, accident, suicide, homicide or:","undetermined",["unknown only","lost","random"],"Undetermined is a category.")
H("769.d.19.D",3,"Entomologists study which insects colonize a body and their stages of development to estimate how long ago a person died. This determines time of death using:","entomology",["geology","astronomy","botany"],"Insect succession indicates time.")
H("769.d.19.D",4,"Blow fly larvae are useful in estimating time of death because:","they develop in predictable stages",["they appear at random","they never reach a body","they live indefinitely"],"Predictable growth.")
H("769.d.20.A",3,"A student labels the skull, femur, humerus and pelvis on a model of the human skeleton. This identifies:","the major bones of the human skeletal system",["muscles of the heart","nerves of the skin","organs of the gut"],"Skeleton bones.")
H("769.d.20.A",4,"The longest bone in the human body is the:","femur",["humerus","tibia","radius"],"Femur is longest.")
H("769.d.20.B",3,"A forensic anthropologist examines a bone fragment under a microscope and sees a pattern of structure unlike that of a deer. This compares the composition and structure of:","human and non-human bones",["glass and plastic","wood and metal","paper and cloth"],"Bone microstructure differs.")
H("769.d.20.B",4,"One way to tell whether a bone is human is to look at its:","microscopic structure and shape",["color only","smell","price"],"Histology and shape.")
H("769.d.20.C",3,"At a field recovery, workers photograph bones in place, record locations and wrap them in paper to protect them. This describes the collection and preservation of:","bone evidence",["glass evidence","fiber evidence","ink evidence"],"Document before removing.")
H("769.d.20.D",3,"An anthropologist studies the pelvis, the skull and the length of the long bones to estimate a person's sex, age and height. This explains the characteristics indicative of:","a person's biological profile",["a person's favorite food","a person's music taste","a person's address"],"Biological profile.")
H("769.d.20.D",4,"The pelvis is useful for estimating sex because it:","differs in shape between males and females",["is always identical","is made of cartilage","changes color"],"Pelvic shape differences.")
H("769.d.20.C",4,"Bone evidence should be stored in a:","dry paper container to prevent mold",["wet plastic bag","sealed jar of water","open box in sunlight"],"Dry paper avoids mold.")
H("769.d.20.E",3,"An odontologist compares X-rays taken before death with the teeth of an unidentified body to confirm who it is. This explains how remains are identified through:","dental records",["library records","phone records","school records"],"Dental records are unique.")
H("769.d.20.E",4,"Teeth are valuable for identification because they:","resist decay and have unique features",["rot quickly","look the same in all people","cannot be recorded"],"Durable and unique.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_108.jsonl"))
